function check([a, b], actual, expected) {
  if (typeof actual !== 'string' || actual.length !== a + b) return false;
  if (!/^[ab]*$/.test(actual)) return false;
  let countA = 0;
  for (const c of actual) if (c === 'a') countA++;
  if (countA !== a || actual.length - countA !== b) return false;
  return !actual.includes('aaa') && !actual.includes('bbb');
}

