function validate([a, b]) {
  if (!Number.isInteger(a) || a < 0 || a > 100) return 'a is an integer between 0 and 100.';
  if (!Number.isInteger(b) || b < 0 || b > 100) return 'b is an integer between 0 and 100.';
  if (a > 2 * (b + 1) || b > 2 * (a + 1)) return 'No valid string exists: one letter outnumbers the other too much.';
  return null;
}

