function strWithout3a3b(a, b) {
  // Depth-first search over (a left, b left, last letter, run length), remembering dead states.
  const dead = new Set();
  const build = (x, y, last, run) => {
    if (x === 0 && y === 0) return '';
    const state = `${x},${y},${last},${run}`;
    if (dead.has(state)) return null;
    for (const letter of ['b', 'a']) {
      const left = letter === 'a' ? x : y;
      if (left === 0) continue;
      const nextRun = letter === last ? run + 1 : 1;
      if (nextRun > 2) continue;
      const rest = letter === 'a' ? build(x - 1, y, 'a', nextRun) : build(x, y - 1, 'b', nextRun);
      if (rest !== null) return letter + rest;
    }
    dead.add(state);
    return null;
  };
  return build(a, b, '', 0);
}

