function generate(rand, size) {
  const max = size === 'large' ? 100 : 8;
  for (;;) {
    const a = Math.floor(rand() * (max + 1));
    let b = Math.floor(rand() * (max + 1));
    // Large inputs often sit on the feasibility boundary, where the greedy choice matters most.
    if (size === 'large' && rand() < 0.4) b = Math.min(max, Math.max(0, Math.floor((a - 2) / 2) + Math.floor(rand() * 2)));
    const pair = rand() < 0.5 ? [a, b] : [b, a];
    if (pair[0] <= 2 * (pair[1] + 1) && pair[1] <= 2 * (pair[0] + 1)) return pair;
  }
}
